          )}
          <Line marginY="4" />
          <Option
            value="new-organization"
            label="New organization"
            prefix={<Icon name="plus" size="xs" onBackground="neutral-weak" />}
            onClick={() => {
              closeOverlay();
              setNewOrgOpen(true);
            }}
          />
        </Column>
      }
    />
  );

  return (
    <Row
      as="header"
      fillWidth
      minHeight="56"
      position="sticky"
      top="0"
      background="page"
      vertical="center"
      zIndex={1}
    >
      <Row gap="4" vertical="center" minWidth={18} paddingX="16">
        <NavIcon
          hide
          m={{ hide: false }}
          active={menuOpen}
          onClick={() => setMenuPath(menuOpen ? null : pathname)}
        />
        <Drawer
          open={menuOpen}
          onClose={closeMenu}
          side="left"
          size="m"
          title="Menu"
          flush
          showClose={false}
          background="page"
          radius="xl-4"
        >
          {/* The header's row, so the workspace and the account stay where
              they were while the drawer covers the header. Sticky, so a long
              menu scrolls under it. */}
          <Row
            fillWidth
            minHeight="56"
            position="sticky"
            zIndex={1}
            background="page"
            paddingLeft="16"
            paddingRight="20"
            gap="12"
            vertical="center"
            horizontal="between"
          >
            <Row gap="4" vertical="center">
              {workspaceMenu}
            </Row>
            <Row vertical="center" gap="12">
              <HeaderActions avatar={avatar} org={org} />
              <IconButton icon="close" variant="tertiary" tooltip="Close" onClick={closeMenu} />
            </Row>
          </Row>
          <Column fillWidth gap="4" padding="8">
            <Sidebar />
          </Column>
        </Drawer>
        {workspaceMenu}
      </Row>
      <Row fillWidth horizontal="center" paddingX="l">
        <Row maxWidth="xl" horizontal="center">
          <Kbar s={{hide: true}} data-border="rounded" radius="full" background="neutral-alpha-weak"
            items={kbar(org)}
          >
            <Button size="s" variant="tertiary" weight="default">
